import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Lavagne, disegni, basi e grafo","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/canvas-disegni-bases-grafo.md","filePath":"user-guide/canvas-disegni-bases-grafo.md"}'),l={name:"user-guide/canvas-disegni-bases-grafo.md"};function r(s,e,t,c,d,m){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="lavagne-disegni-basi-e-grafo" tabindex="-1">Lavagne, disegni, basi e grafo <a class="header-anchor" href="#lavagne-disegni-basi-e-grafo" aria-label="Permalink to &quot;Lavagne, disegni, basi e grafo&quot;">​</a></h1><h2 id="lavagne-canvas" tabindex="-1">Lavagne (canvas) <a class="header-anchor" href="#lavagne-canvas" aria-label="Permalink to &quot;Lavagne (canvas)&quot;">​</a></h2><p><em>Nuova lavagna</em> crea un file <code>.canvas</code> (formato JSON Canvas): una superficie infinita con <strong>schede</strong> di testo, note, file, immagini e link, collegate da <strong>frecce</strong> con etichetta, e raggruppabili. Si usa con trascinamento, zoom con la rotella o i gesti del trackpad, selezione multipla e le scorciatoie indicate nella barra della lavagna. Le note incorporate si aprono con doppio clic.</p><h2 id="disegni" tabindex="-1">Disegni <a class="header-anchor" href="#disegni" aria-label="Permalink to &quot;Disegni&quot;">​</a></h2><p><em>Nuovo disegno</em> crea un file <code>.excalidraw</code> (JSON standard in chiaro, apribile anche con excalidraw.com), modificabile con l&#39;editor di disegno integrato (forme, frecce, testo, tratto libero, librerie). Funziona <strong>offline</strong>: gli asset sono inclusi nell&#39;app. Dove nasce il file, come si chiama e come si apre (modifica, sola lettura, zen) si sceglie in <em>Impostazioni &gt; Disegni</em>; lì si fissano anche i colori, il carattere e la dimensione predefiniti dei nuovi elementi e l&#39;esportazione automatica. Le impostazioni stanno in <code>.clarae/drawing.json</code> e viaggiano con il vault (in un vault della 1.x collegato al cloud possono stare ancora nella cartella con il nome precedente: vedi <a href="./installazione.html#aggiornare-dalla-1x">Aggiornare dalla 1.x</a>). I disegni creati con la 1.x si aprono come prima: i dati dei vostri elementi (formule, frame, schede delle note) e le impostazioni del singolo disegno passano al nome nuovo solo quando li modificate o salvate il disegno, e un dispositivo con la 1.4 non riconosce più, su un disegno salvato dalla 1.5, le formule modificabili e l&#39;ordine delle diapositive.</p><h3 id="nelle-note" tabindex="-1">Nelle note <a class="header-anchor" href="#nelle-note" aria-label="Permalink to &quot;Nelle note&quot;">​</a></h3><ul><li><code>![[disegno.excalidraw]]</code> mostra un&#39;anteprima; <code>|400</code> ne fissa la larghezza e <code>|left</code>, <code>|right</code>, <code>|center</code>, <code>|left-wrap</code>, <code>|right-wrap</code> l&#39;allineamento. Doppio clic apre il disegno.</li><li>Si incorpora anche <strong>una parte</strong>: <code>![[disegno.excalidraw#frame=Nome]]</code>, <code>#clippedframe=</code>, <code>#group=</code>, <code>#area=</code>.</li><li>Un elemento con un link <code>[[Nota]]</code> (o un indirizzo web) lo apre con un clic; ⌘/Ctrl+passaggio ne mostra l&#39;anteprima. Il testo del disegno (così come è stato scritto, anche quando è andato a capo dentro una forma), il TeX delle formule e i nomi delle cornici si trovano con la ricerca, i link compaiono nei backlink e, se rinomini la nota, il link nel disegno si aggiorna.</li><li>Dal comando <code>/disegno</code> o da <em>Inserisci disegno</em> si aggiunge un disegno alla nota.</li><li>Il disegno incorporato segue il tema: in tema scuro la nota mostra la versione scura, e passa dall&#39;una all&#39;altra quando cambi tema (anche quando, con il tema «Sistema», è il sistema operativo a cambiarlo). Stampa ed esportazione della nota usano sempre la versione chiara.</li></ul><h3 id="dentro-il-disegno" tabindex="-1">Dentro il disegno <a class="header-anchor" href="#dentro-il-disegno" aria-label="Permalink to &quot;Dentro il disegno&quot;">​</a></h3><ul><li><strong>Inserisci</strong> immagini, note (come schede) e altri disegni dal vault, anche trascinandoli dall&#39;esplorazione file nel punto desiderato; <em>Crea una nota e aggiungi la scheda</em>; <em>Sposta la selezione in un nuovo disegno</em>.</li><li><strong>Formule LaTeX</strong> (<em>Inserisci formula</em>, doppio clic per modificarla) e <strong>diagrammi Mermaid</strong> (testo → elementi modificabili): tutto locale, senza rete.</li><li><strong>Azioni sulla scena</strong> (palette dei comandi o pannello <em>Strumenti del disegno</em>, con ricerca, preferiti e usati di recente): distribuzione e allineamento, Auto Layout, colore e stile, schemi di colori, forme (riquadri, Boolean Operations, ellisse divisa), frecce (collega, a gomito, passo successivo), testo, ripetizione, mappa mentale da un elenco indentato, calendari, vignette e nuvolette, linea organica. Ogni azione si può annullare e ha un comando assegnabile a una scorciatoia.</li><li><strong>Strumenti dei plugin Excalidraw di terze parti</strong> (menu ⋮ della barra): <em>Disegna per la forma</em> (Maiusc+X) trasforma un tratto a mano libera in una forma, <em>Secchiello riempimento</em> (B) riempie la forma o l&#39;area cliccata, <em>Selezione a lazo</em> seleziona gli elementi circondati da un tratto libero. Barra, pulsanti e menu sono al 90% della dimensione standard di Excalidraw; il menu principale di Excalidraw (ricerca, guida, link) non è mostrato.</li><li><strong>Penne e puntatore laser</strong>: penna fine, pennarello, evidenziatore e laser sono comandi con scorciatoia propria.</li><li><strong>Libreria di forme</strong>: è una sola per vault, condivisa da tutti i disegni aperti (una forma aggiunta in un pannello compare subito negli altri) e sincronizzata. Se due dispositivi aggiungono forme diverse, restano entrambe.</li><li><strong>Navigazione</strong>: accanto al controllo dello zoom, in basso a sinistra, <em>Zoom sulla selezione</em> inquadra gli elementi selezionati, o tutto il disegno se non c&#39;è selezione (funziona anche in sola visualizzazione), e <em>Mini-mappa</em> mostra o nasconde una miniatura dell&#39;intero disegno con la porzione visibile evidenziata. Nella mini-mappa un clic o un trascinamento spostano la vista; con il focus, le frecce la scorrono (Maiusc per passi più ampi) e Home inquadra tutto. La mini-mappa resta visibile o nascosta su questo dispositivo, non si sincronizza, e non compare in modalità Zen né in presentazione. Entrambi sono anche comandi della palette.</li><li><strong>Scheda Slideshow</strong> (barra destra, scheda <em>Slide</em>, con un disegno aperto): come nei plugin Excalidraw di terze parti elenca le cornici con miniatura e permette di avviare la presentazione (anche da una diapositiva), stamparla o salvarla in PDF, descrivere il disegno come testo e impostare ripetizione, contatore e note. Ogni cornice si può rinominare, spostare su/giù, escludere dalla presentazione (resta sulla lavagna) e ha le proprie <em>note del relatore</em> in Markdown, salvate da sole. Le impostazioni stanno nel file del disegno.</li><li><strong>Presentazione</strong>: ogni cornice è una diapositiva (ordinate per numero, poi per nome, poi per posizione); frecce, Pagina su/giù, Spazio, Home/Fine navigano, Esc esce. Le <em>note del relatore</em> si impostano con <em>Modifica le note del relatore</em>.</li><li><strong>Descrivi il disegno come testo</strong>: elenco di contenuto, cornici, testi e link, per chi non può vedere la lavagna.</li></ul><h3 id="esportare-e-importare" tabindex="-1">Esportare e importare <a class="header-anchor" href="#esportare-e-importare" aria-label="Permalink to &quot;Esportare e importare&quot;">​</a></h3><ul><li><em>Esporta</em>: PNG o SVG di tutto il disegno, della selezione o di una cornice, con scala, margine, tema e scena incorporata (si può poi trascinare di nuovo nell&#39;editor); salva nel vault, con nome, copia o stampa/PDF.</li><li><strong>Esportazione automatica</strong> accanto al file (<code>Disegno.excalidraw.png</code>, <code>.svg</code>, anche <code>.dark</code>/<code>.light</code>): parte quindici secondi dopo l&#39;ultimo salvataggio, quando il lavoro si ferma, e subito alla chiusura del disegno, non a ogni salvataggio; si può scegliere per singolo disegno.</li><li><strong>Importa</strong>: un <code>.excalidraw.md</code> dei plugin Excalidraw di terze parti (<em>Converti un disegno .excalidraw.md</em>) diventa un <code>.excalidraw</code> accanto all&#39;originale, che resta intatto (le immagini incorporate sono incluse e le formule LaTeX tornano formule modificabili, disegnate all&#39;apertura); una libreria <code>.excalidrawlib</code> copiata nel vault si importa in libreria e la libreria si esporta come <code>Library.excalidrawlib</code>.</li></ul><h3 id="limiti" tabindex="-1">Limiti <a class="header-anchor" href="#limiti" aria-label="Permalink to &quot;Limiti&quot;">​</a></h3><p>L&#39;editor parla la lingua dell&#39;app (inglese e italiano). Un disegno oltre 8 MB (di solito per le immagini incorporate) non viene più indicizzato: il suo testo non si trova con la ricerca e i suoi link non compaiono nei backlink; oltre 10 MB anche salvataggio e sincronizzazione rallentano. L&#39;editor lo segnala in entrambi i casi, misurando il file così come è salvato. Un&#39;immagine oltre 10 MB non si inserisce dall&#39;editor; se un file <code>.excalidraw</code> ne contiene già una (creata con un altro strumento) viene salvato lo stesso e l&#39;indicizzazione ne scrive un avviso nel registro.</p><p>Non ci sono le funzioni dei plugin Excalidraw di terze parti che richiedono script utente, rete o una penna fisica (ExcaliAI, OCR, …) né alcune azioni minori (Icon Library, Image Occlusion, LayerManager, Crop Vintage Mask, Collaboration Frame, Capture Note, Folder Note); dettagli in <code>docs/qa/parita-funzionale-m1.md</code>. Una modifica fatta in contemporanea sulla stessa forma da due dispositivi tiene la versione più recente; le modifiche a forme diverse si fondono. Lo stesso vale mentre il disegno è aperto: se il file cambia (la sincronizzazione, l&#39;altro pannello dello stesso disegno) quando ci sono modifiche non ancora salvate, le due versioni vengono fuse e il disegno continua senza interruzioni. Solo quando la fusione non è ammessa — la modifica di un altro utente in un vault condiviso — compare l&#39;avviso con <em>Ricarica</em>, <em>Sovrascrivi</em> e <em>Tieni entrambe</em>, che salva la tua versione in una copia accanto al file. Lo stesso avviso compare in due altri casi: in un vault condiviso, per un disegno sincronizzato l&#39;ultima volta prima della 1.6 (non se ne conosce ancora l&#39;autore, finché non viene sincronizzato di nuovo), e quando stai ancora disegnando o scrivendo da più di venti secondi mentre la fusione aspetta che tu finisca. L&#39;amministratore può disattivare separatamente formule, Mermaid, esportazione automatica e azioni (flag <code>drawing_*</code> del profilo di configurazione).</p><h2 id="basi-bases" tabindex="-1">Basi (Bases) <a class="header-anchor" href="#basi-bases" aria-label="Permalink to &quot;Basi (Bases)&quot;">​</a></h2><p><em>Nuova base</em> crea un file <code>.base</code>: una <strong>vista tabellare</strong> sulle note del vault, costruita sulle proprietà. Si scelgono colonne, filtri, ordinamenti e raggruppamenti; si possono modificare i valori direttamente nella tabella (la modifica scrive la proprietà nella nota). Il formato <code>.base</code> è condiviso con altri editor; le funzioni non supportate vengono segnalate invece di essere perse (il file non si rovina). Una base si può incorporare in una nota con <code>![[nome.base]]</code>.</p><h2 id="vista-grafo" tabindex="-1">Vista grafo <a class="header-anchor" href="#vista-grafo" aria-label="Permalink to &quot;Vista grafo&quot;">​</a></h2><p><em>Apri vista grafo</em> (<code>Mod+Maiusc+G</code>) mostra i documenti del vault come nodi e i link come archi: filtri per tag, cartella o ricerca, colori per gruppo, dimensione per numero di link, cursore del tempo. <em>Apri grafo locale</em> mostra solo il vicinato del documento corrente, con la profondità regolabile; si può centrare su una nota, una presentazione, un disegno o una lavagna. Il grafo si sposta e si ingrandisce con mouse o tastiera (frecce e <code>+</code>/<code>-</code>); il grafo del vault non include altri vault.</p><h3 id="disegni-lavagne-e-basi-come-nodi" tabindex="-1">Disegni, lavagne e basi come nodi <a class="header-anchor" href="#disegni-lavagne-e-basi-come-nodi" aria-label="Permalink to &quot;Disegni, lavagne e basi come nodi&quot;">​</a></h3><p>Oltre alle note, il grafo mostra i <strong>disegni</strong> (<code>.excalidraw</code>), le <strong>lavagne</strong> (<code>.canvas</code>) e le <strong>basi</strong> (<code>.base</code>). Un disegno o una lavagna ha come link quelli dei suoi elementi; una base compare solo come destinazione, perché non contiene link. I tag restano delle sole note: un filtro per tag nasconde questi nodi, come nasconde gli allegati. Si tolgono tutti insieme con la casella <em>Disegni, lavagne e basi</em> nei filtri (nelle impostazioni del grafo).</p><h3 id="vista-3d" tabindex="-1">Vista 3D <a class="header-anchor" href="#vista-3d" aria-label="Permalink to &quot;Vista 3D&quot;">​</a></h3><p>Il pulsante a forma di cubo nella barra del grafo (o <em>Apri vista grafo in 3D</em> dalla palette e dal ribbon, <em>Grafo: passa tra 2D e 3D</em> per alternare) disegna lo stesso grafo nello spazio. Filtri, gruppi, timelapse e grafo locale funzionano come nel 2D. Funziona sul desktop e nel workbench web.</p><ul><li><strong>Per dispositivo.</strong> La scelta 2D/3D vale per questo dispositivo (o questo browser): dipende dalla scheda grafica e dallo schermo, quindi non entra nel vault e non si sincronizza. Su un dispositivo nuovo il grafo si apre in 2D.</li><li><strong>Icone, forme e legenda.</strong> Il grafo si disegna in tre modi, secondo quanti nodi mostra. <strong>Fino a 1.000 nodi</strong> ogni nodo ha l&#39;icona del suo tipo (le stesse dell&#39;esploratore dei file: nota, presentazione, disegno, lavagna, base, immagine, PDF, audio, video, altri file, tag, nota non ancora creata) sul colore del suo gruppo o del suo tipo. <strong>Da 1.001 a 2.000 nodi</strong> ogni nodo è un solido con la forma del suo tipo (sfera per note e presentazioni, cubo per i disegni, ottaedro per le lavagne, cilindro per le basi, cono per gli allegati, toro per i tag, icosaedro per le note non ancora create), sempre sul colore del gruppo o del tipo: è più leggero da disegnare. <strong>Oltre 2.000 nodi</strong> i nodi sono punti. Una legenda mostra quanti nodi ci sono per tipo, con l&#39;icona o con la forma di ciò che si vede; si spegne dalle impostazioni.</li><li><strong>Con il mouse.</strong> Trascinare lo sfondo ruota la vista, la rotella ingrandisce. Un click su un nodo lo seleziona e porta la camera su di lui; un click sul nodo già selezionato, o un doppio click, lo apre; Ctrl o Cmd+click lo apre in una nuova scheda. Passando sopra un nodo, lui e i suoi vicini restano accesi, gli altri si attenuano e i suoi link si evidenziano.</li><li><strong>Con la tastiera.</strong> Con il focus sul grafo: frecce per ruotare, <code>+</code> e <code>-</code> per lo zoom, <code>0</code> per adattare tutto allo schermo, <code>[</code> e <code>]</code> per passare da un nodo all&#39;altro (si parte dal più connesso), Invio per aprire il nodo selezionato, Esc per togliere la selezione.</li><li><strong>Nodi fissati.</strong> Fino a 2.000 nodi ogni nodo si può <strong>trascinare</strong>: resta dove lo lasciate, anche quando il grafo si aggiorna. Il pulsante <em>Sblocca i nodi fissati</em> (con il numero) li libera tutti.</li><li><strong>Etichette.</strong> Compaiono per il nodo selezionato e i suoi vicini e per i più connessi vicini alla camera, al massimo 40 alla volta.</li><li><strong>Opzioni del 3D</strong> (impostazioni del grafo, sezione <em>Vista 3D</em>, salvate nel vault): <em>Link reciproci curvi</em> (due note che si rimandano l&#39;una all&#39;altra hanno due archi invece di una linea), <em>Legenda</em>, <em>Nodi mostrati (massimo)</em> da 500 a 5.000.</li><li><strong>Con «riduci movimento»</strong> attivo nel sistema la camera salta alla nuova posizione invece di muoversi.</li></ul><p><strong>Limiti.</strong></p><ul><li><strong>Al massimo 5.000 nodi</strong> (o il numero scelto in <em>Nodi mostrati (massimo)</em>): se il vault ne ha di più, il 3D mostra i più connessi e la riga di stato in basso dice «Mostrati N nodi su M». Per un vault grande usate il 2D, che regge più nodi.</li><li><strong>Oltre 2.000 nodi</strong> i nodi sono punti: non si trascinano (fino a 2.000, icone e solidi, sì).</li><li><strong>Senza WebGL2</strong> il grafo resta in 2D e un avviso lo dice. Succede anche se il contesto grafico va perso, se ci sono già quattro grafi 3D aperti o se la vista non parte; scegliere di nuovo il 3D riprova.</li><li><strong>Su un dispositivo senza scheda grafica</strong> la vista 3D è più lenta (nelle nostre misure, da circa 11 a 29 fotogrammi al secondo con il rasterizzatore software contro i 60 con una GPU). Le misure sono su un solo computer, con carico variabile, e un grafo sintetico; sulla finestra reale dell&#39;applicazione desktop non sono ancora state fatte, e le forme dei solidi non sono ancora state viste lì. I dettagli sono in <code>docs/qa/graph-3d-benchmark.md</code>.</li></ul>',25)])])}const p=a(l,[["render",r]]);export{g as __pageData,p as default};
